void DetectSpike(MLContext mlContext, int docSize, IDataView productSales)
{
    Console.WriteLine("Detect temporary changes in pattern");

    // STEP 2: Set the training algorithm
    // <SnippetAddSpikeTrainer>
    var iidSpikeEstimator = mlContext.Transforms.DetectIidSpike(outputColumnName: nameof(ProductSalesPrediction.Prediction), inputColumnName: nameof(ProductSalesData.numSales), confidence: 95d, pvalueHistoryLength: docSize / 4);
    // </SnippetAddSpikeTrainer>

    // STEP 3: Create the transform
    // Create the spike detection transform
    Console.WriteLine("=============== Training the model ===============");
    // <SnippetTrainModel1>
    ITransformer iidSpikeTransform = iidSpikeEstimator.Fit(CreateEmptyDataView(mlContext));
    // </SnippetTrainModel1>

    Console.WriteLine("=============== End of training process ===============");
        //Apply data transformation to create predictions.
    // <SnippetTransformData1>
    IDataView transformedData = iidSpikeTransform.Transform(productSales);
    // </SnippetTransformData1>

    // <SnippetCreateEnumerable1>
    var predictions = mlContext.Data.CreateEnumerable<ProductSalesPrediction>(transformedData, reuseRowObject: false);
    // </SnippetCreateEnumerable1>

    // <SnippetDisplayHeader1>
    Console.WriteLine("Alert\tScore\tP-Value");
    // </SnippetDisplayHeader1>

    // <SnippetDisplayResults1>
    foreach (var p in predictions)
    {
        if (p.Prediction is not null)
        {
            var results = $"{p.Prediction[0]}\t{p.Prediction[1]:f2}\t{p.Prediction[2]:F2}";

            if (p.Prediction[0] == 1)
            {
                results += " <-- Spike detected";
            }

            Console.WriteLine(results);
        }
    }
    Console.WriteLine("");
    // </SnippetDisplayResults1>
}

void DetectChangepoint(MLContext mlContext, int docSize, IDataView productSales)
{
    Console.WriteLine("Detect Persistent changes in pattern");

    //STEP 2: Set the training algorithm
    // <SnippetAddChangePointTrainer>
    var iidChangePointEstimator = mlContext.Transforms.DetectIidChangePoint(outputColumnName: nameof(ProductSalesPrediction.Prediction), inputColumnName: nameof(ProductSalesData.numSales), confidence: 95d, changeHistoryLength: docSize / 4);
    // </SnippetAddChangePointTrainer>

    //STEP 3: Create the transform
    Console.WriteLine("=============== Training the model Using Change Point Detection Algorithm===============");
    // <SnippetTrainModel2>
    var iidChangePointTransform = iidChangePointEstimator.Fit(CreateEmptyDataView(mlContext));
    // </SnippetTrainModel2>
    Console.WriteLine("=============== End of training process ===============");

    //Apply data transformation to create predictions.
    // <SnippetTransformData2>
    IDataView transformedData = iidChangePointTransform.Transform(productSales);
    // </SnippetTransformData2>

    // <SnippetCreateEnumerable2>
    var predictions = mlContext.Data.CreateEnumerable<ProductSalesPrediction>(transformedData, reuseRowObject: false);
    // </SnippetCreateEnumerable2>

    // <SnippetDisplayHeader2>
    Console.WriteLine("Alert\tScore\tP-Value\tMartingale value");
    // </SnippetDisplayHeader2>

    // <SnippetDisplayResults2>
    foreach (var p in predictions)
    {
        if (p.Prediction is not null)
        {
            var results = $"{p.Prediction[0]}\t{p.Prediction[1]:f2}\t{p.Prediction[2]:F2}\t{p.Prediction[3]:F2}";

            if (p.Prediction[0] == 1)
            {
                results += " <-- alert is on, predicted changepoint";
            }
            Console.WriteLine(results);
        }
    }
    Console.WriteLine("");
    // </SnippetDisplayResults2>
}

// <SnippetCreateEmptyDataView>
IDataView CreateEmptyDataView(MLContext mlContext) {
    // Create empty DataView. We just need the schema to call Fit() for the time series transforms
    IEnumerable<ProductSalesData> enumerableData = new List<ProductSalesData>();
    return mlContext.Data.LoadFromEnumerable(enumerableData);
}
// </SnippetCreateEmptyDataView>

// <SnippetAddUsings>
using Microsoft.ML;
using Microsoft.ML.Data;
using SentimentAnalysis;
using static Microsoft.ML.DataOperationsCatalog;
// </SnippetAddUsings>

// <SnippetDeclareGlobalVariables>
string _dataPath = Path.Combine(Environment.CurrentDirectory, "Data", "yelp_labelled.txt");
// </SnippetDeclareGlobalVariables>

// Create ML.NET context/local environment - allows you to add steps in order to keep everything together
// as you discover the ML.NET trainers and transforms
// <SnippetCreateMLContext>
MLContext mlContext = new MLContext();
// </SnippetCreateMLContext>

// <SnippetCallLoadData>
TrainTestData splitDataView = LoadData(mlContext);
// </SnippetCallLoadData>

// <SnippetCallBuildAndTrainModel>
ITransformer model = BuildAndTrainModel(mlContext, splitDataView.TrainSet);
// </SnippetCallBuildAndTrainModel>

// <SnippetCallEvaluate>
Evaluate(mlContext, model, splitDataView.TestSet);
// </SnippetCallEvaluate>

// <SnippetCallUseModelWithSingleItem>
UseModelWithSingleItem(mlContext, model);
// </SnippetCallUseModelWithSingleItem>

// <SnippetCallUseModelWithBatchItems>
UseModelWithBatchItems(mlContext, model);
// </SnippetCallUseModelWithBatchItems>

Console.WriteLine();
Console.WriteLine("=============== End of process ===============");

TrainTestData LoadData(MLContext mlContext)
{
    // Note that this case, loading your training data from a file,
    // is the easiest way to get started, but ML.NET also allows you
    // to load data from databases or in-memory collections.
    // <SnippetLoadData>
    IDataView dataView = mlContext.Data.LoadFromTextFile<SentimentData>(_dataPath, hasHeader: false);
    // </SnippetLoadData>

    // You need both a training dataset to train the model and a test dataset to evaluate the model.
    // Split the loaded dataset into train and test datasets
    // Specify test dataset percentage with the `testFraction`parameter
    // <SnippetSplitData>
    TrainTestData splitDataView = mlContext.Data.TrainTestSplit(dataView, testFraction: 0.2);
    // </SnippetSplitData>

    // <SnippetReturnSplitData>
    return splitDataView;
    // </SnippetReturnSplitData>
}

ITransformer BuildAndTrainModel(MLContext mlContext, IDataView splitTrainSet)
{
    // Create a flexible pipeline (composed by a chain of estimators) for creating/training the model.
    // This is used to format and clean the data.
    // Convert the text column to numeric vectors (Features column)
    // <SnippetFeaturizeText>
    var estimator = mlContext.Transforms.Text.FeaturizeText(outputColumnName: "Features", inputColumnName: nameof(SentimentData.SentimentText))
    //</SnippetFeaturizeText>
    // append the machine learning task to the estimator
    // <SnippetAddTrainer>
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(labelColumnName: "Label", featureColumnName: "Features"));
    // </SnippetAddTrainer>

    // Create and train the model based on the dataset that has been loaded, transformed.
    // <SnippetTrainModel>
    Console.WriteLine("=============== Create and Train the Model ===============");
    var model = estimator.Fit(splitTrainSet);
    Console.WriteLine("=============== End of training ===============");
    Console.WriteLine();
    // </SnippetTrainModel>

    // Returns the model we trained to use for evaluation.
    // <SnippetReturnModel>
    return model;
    // </SnippetReturnModel>
}

void Evaluate(MLContext mlContext, ITransformer model, IDataView splitTestSet)
{
    // Evaluate the model and show accuracy stats

    //Take the data in, make transformations, output the data.
    // <SnippetTransformData>
    Console.WriteLine("=============== Evaluating Model accuracy with Test data===============");
    IDataView predictions = model.Transform(splitTestSet);
    // </SnippetTransformData>

    // BinaryClassificationContext.Evaluate returns a BinaryClassificationEvaluator.CalibratedResult
    // that contains the computed overall metrics.
    // <SnippetEvaluate>
    CalibratedBinaryClassificationMetrics metrics = mlContext.BinaryClassification.Evaluate(predictions, "Label");
    // </SnippetEvaluate>

    // The Accuracy metric gets the accuracy of a model, which is the proportion
    // of correct predictions in the test set.

    // The AreaUnderROCCurve metric is equal to the probability that the algorithm ranks
    // a randomly chosen positive instance higher than a randomly chosen negative one
    // (assuming 'positive' ranks higher than 'negative').

    // The F1Score metric gets the model's F1 score.
    // The F1 score is the harmonic mean of precision and recall:
    //  2 * precision * recall / (precision + recall).

    // <SnippetDisplayMetrics>
    Console.WriteLine();
    Console.WriteLine("Model quality metrics evaluation");
    Console.WriteLine("--------------------------------");
    Console.WriteLine($"Accuracy: {metrics.Accuracy:P2}");
    Console.WriteLine($"Auc: {metrics.AreaUnderRocCurve:P2}");
    Console.WriteLine($"F1Score: {metrics.F1Score:P2}");
    Console.WriteLine("=============== End of model evaluation ===============");
    //</SnippetDisplayMetrics>
}

void UseModelWithSingleItem(MLContext mlContext, ITransformer model)
{
    // <SnippetCreatePredictionEngine1>
    PredictionEngine<SentimentData, SentimentPrediction> predictionFunction = mlContext.Model.CreatePredictionEngine<SentimentData, SentimentPrediction>(model);
    // </SnippetCreatePredictionEngine1>

    // <SnippetCreateTestIssue1>
    SentimentData sampleStatement = new SentimentData
    {
        SentimentText = "This was a very bad steak"
    };
    // </SnippetCreateTestIssue1>

    // <SnippetPredict>
    var resultPrediction = predictionFunction.Predict(sampleStatement);
    // </SnippetPredict>
    // <SnippetOutputPrediction>
    Console.WriteLine();
    Console.WriteLine("=============== Prediction Test of model with a single sample and test dataset ===============");

    Console.WriteLine();
    Console.WriteLine($"Sentiment: {resultPrediction.SentimentText} | Prediction: {(Convert.ToBoolean(resultPrediction.Prediction) ? "Positive" : "Negative")} | Probability: {resultPrediction.Probability} ");

    Console.WriteLine("=============== End of Predictions ===============");
    Console.WriteLine();
    // </SnippetOutputPrediction>
}

void UseModelWithBatchItems(MLContext mlContext, ITransformer model)
{
    // Adds some comments to test the trained model's data points.
    // <SnippetCreateTestIssues>
    IEnumerable<SentimentData> sentiments = new[]
    {
        new SentimentData
        {
            SentimentText = "This was a horrible meal"
        },
        new SentimentData
        {
            SentimentText = "I love this spaghetti."
        }
    };
    // </SnippetCreateTestIssues>

    // Load batch comments just created
    // <SnippetPrediction>
    IDataView batchComments = mlContext.Data.LoadFromEnumerable(sentiments);

    IDataView predictions = model.Transform(batchComments);

    // Use model to predict whether comment data is Positive (1) or Negative (0).
    IEnumerable<SentimentPrediction> predictedResults = mlContext.Data.CreateEnumerable<SentimentPrediction>(predictions, reuseRowObject: false);
    // </SnippetPrediction>

    // <SnippetAddInfoMessage>
    Console.WriteLine();

    Console.WriteLine("=============== Prediction Test of loaded model with multiple samples ===============");
    // </SnippetAddInfoMessage>

    Console.WriteLine();

    // <SnippetDisplayResults>
    foreach (SentimentPrediction prediction  in predictedResults)
    {
        Console.WriteLine($"Sentiment: {prediction.SentimentText} | Prediction: {(Convert.ToBoolean(prediction.Prediction) ? "Positive" : "Negative")} | Probability: {prediction.Probability} ");
    }
    Console.WriteLine("=============== End of predictions ===============");
    // </SnippetDisplayResults>
}

// <SnippetAddUsings>
using Microsoft.ML.Data;
// </SnippetAddUsings>

namespace SentimentAnalysis
{
    // <SnippetDeclareTypes>
    public class SentimentData
    {
        [LoadColumn(0)]
        public string? SentimentText;

        [LoadColumn(1), ColumnName("Label")]
        public bool Sentiment;
    }

    public class SentimentPrediction : SentimentData
    {

        [ColumnName("PredictedLabel")]
        public bool Prediction { get; set; }

        public float Probability { get; set; }

        public float Score { get; set; }
    }
    // </SnippetDeclareTypes>
}

// <SnippetAddUsings>
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.ML.Transforms;
// </SnippetAddUsings>

// <SnippetDeclareGlobalVariables>
string _modelPath = Path.Combine(Environment.CurrentDirectory, "sentiment_model");
// </SnippetDeclareGlobalVariables>

// Create MLContext to be shared across the model creation workflow objects
// <SnippetCreateMLContext>
MLContext mlContext = new MLContext();
// </SnippetCreateMLContext>

// Dictionary to encode words as integers.
// <SnippetCreateLookupMap>
var lookupMap = mlContext.Data.LoadFromTextFile(Path.Combine(_modelPath, "imdb_word_index.csv"),
    columns: new[]
        {
            new TextLoader.Column("Words", DataKind.String, 0),
            new TextLoader.Column("Ids", DataKind.Int32, 1),
        },
    separatorChar: ','
    );
// </SnippetCreateLookupMap>

// The model expects the input feature vector to be a fixed length vector.
// This action resizes the variable length array generated by the lookup map
// to a fixed length vector. If there are less than 600 words in the sentence,
// the remaining indices will be filled with zeros. If there are more than
// 600 words in the sentence, then the array is truncated at 600.
// <SnippetResizeFeatures>
Action<VariableLength, FixedLength> ResizeFeaturesAction = (s, f) =>
{
    var features = s.VariableLengthFeatures;
    Array.Resize(ref features, Config.FeatureLength);
    f.Features = features;
};
// </SnippetResizeFeatures>

// Load the TensorFlow model.
// <SnippetLoadTensorFlowModel>
TensorFlowModel tensorFlowModel = mlContext.Model.LoadTensorFlowModel(_modelPath);
// </SnippetLoadTensorFlowModel>

// <SnippetGetModelSchema>
DataViewSchema schema = tensorFlowModel.GetModelSchema();
Console.WriteLine(" =============== TensorFlow Model Schema =============== ");
var featuresType = (VectorDataViewType)schema["Features"].Type;
Console.WriteLine($"Name: Features, Type: {featuresType.ItemType.RawType}, Size: ({featuresType.Dimensions[0]})");
var predictionType = (VectorDataViewType)schema["Prediction/Softmax"].Type;
Console.WriteLine($"Name: Prediction/Softmax, Type: {predictionType.ItemType.RawType}, Size: ({predictionType.Dimensions[0]})");

// </SnippetGetModelSchema>

// <SnippetTokenizeIntoWords>
IEstimator<ITransformer> pipeline =
    // Split the text into individual words
    mlContext.Transforms.Text.TokenizeIntoWords("TokenizedWords", "ReviewText")
    // </SnippetTokenizeIntoWords>

    // <SnippetMapValue>
    // Map each word to an integer value. The array of integer makes up the input features.
    .Append(mlContext.Transforms.Conversion.MapValue("VariableLengthFeatures", lookupMap,
        lookupMap.Schema["Words"], lookupMap.Schema["Ids"], "TokenizedWords"))
    // </SnippetMapValue>

    // <SnippetCustomMapping>
    // Resize variable length vector to fixed length vector.
    .Append(mlContext.Transforms.CustomMapping(ResizeFeaturesAction, "Resize"))
    // </SnippetCustomMapping>

    // <SnippetScoreTensorFlowModel>
    // Passes the data to TensorFlow for scoring
    .Append(tensorFlowModel.ScoreTensorFlowModel("Prediction/Softmax", "Features"))
    // </SnippetScoreTensorFlowModel>

    // <SnippetCopyColumns>
    // Retrieves the 'Prediction' from TensorFlow and copies to a column
    .Append(mlContext.Transforms.CopyColumns("Prediction", "Prediction/Softmax"));
    // </SnippetCopyColumns>

// <SnippetCreateModel>
// Create an executable model from the estimator pipeline
IDataView dataView = mlContext.Data.LoadFromEnumerable(new List<MovieReview>());
ITransformer model = pipeline.Fit(dataView);
// </SnippetCreateModel>

// <SnippetCallPredictSentiment>
PredictSentiment(mlContext, model);
// </SnippetCallPredictSentiment>

void PredictSentiment(MLContext mlContext, ITransformer model)
{
    // <SnippetCreatePredictionEngine>
    var engine = mlContext.Model.CreatePredictionEngine<MovieReview, MovieReviewSentimentPrediction>(model);
    // </SnippetCreatePredictionEngine>

    // <SnippetCreateTestData>
    var review = new MovieReview()
    {
        ReviewText = "this film is really good"
    };
    // </SnippetCreateTestData>

    // Predict with TensorFlow pipeline.
    // <SnippetPredict>
    var sentimentPrediction = engine.Predict(review);
    // </SnippetPredict>

    // <SnippetDisplayPredictions>
    Console.WriteLine($"Number of classes: {sentimentPrediction.Prediction?.Length}");
    Console.WriteLine($"Is sentiment/review positive? {(sentimentPrediction.Prediction?[1] > 0.5 ? "Yes." : "No.")}");
    // </SnippetDisplayPredictions>

    /////////////////////////////////// Expected output ///////////////////////////////////
    //
    // Name: Features, Type: System.Int32, Size: 600
    // Name: Prediction/Softmax, Type: System.Single, Size: 2
    //
    // Number of classes: 2
    // Is sentiment/review positive ? Yes
    // Prediction Confidence: 0.65
}

